Instance.ref.Members:
func GetClockElement(): GuiRawElementBase^ { return clock; }
prop ClockElement: GuiRawElementBase^ {GetClockElement}

@cpp:Private
static func Digits(value: int): string
{
  if (value < 10) { return "0" & (cast string value); }
  return cast string value;
}

@cpp:Private
static func CurrentTime(): string
{
  var time = Sys::GetLocalTime();
  return Digits(time.hour) & ":" & Digits(time.minute) & ":" & Digits(time.second);
}

@cpp:Private
static func Tick(element: GuiRawElementBase^): IGuiAnimation^
${
  while (true)
  {
    $Wait (cast UInt64 1000);
    element.Data = CurrentTime();
  }
}
